from collections import namedtuple
from ..section_generic import TextBasedSectionGeneric


EpcLine = namedtuple('EpcLine', ['line', 'exec', 'tab_count'])


class EpcSectionGeneric(TextBasedSectionGeneric):
    EDAEMON_PORT = 10000
    TAB = ' ' * 4

    def __init__(self):
        super().__init__()
        self.nr = False

    def convert_epc_line(self, epc_line):
        return self.TAB * epc_line.tab_count + (self.put_in_exec(epc_line.line) if epc_line.exec else epc_line.line)

    def _adjust_printing_style(self, subsection_content):
        return [self.convert_epc_line(epc_line) for epc_line in subsection_content]

    @staticmethod
    def put_in_exec(line: str) -> str:
        return f"exec(\"{line}\")"
